  const labels={projects:'프로젝트',tasks:'업무',employees:'직원',expenses:'지출',purchases:'구매',resources:'자료',submissions:'제출본',reviews:'검토',legacyRecords:'이전 기록'};
  const statusNames={assigned:'배정',active:'진행',submitted:'결과 제출',complete:'완료',blocked:'진행 불가',revision:'보완 요청',hold:'보류',cancelled:'취소',closed:'종료',rejected:'미선정',reviewed:'검토 완료',pending:'대기',planned:'계획',unpaid:'확정 미지급',partial:'부분 지급',paid:'지급 완료',refunded:'환불',missing:'미수취',received:'수취',supplement:'보완',requested:'요청',ordered:'주문',arrived:'입고',inspected:'검수 완료',notOrdered:'미주문'};
