  const state={uid:'',epoch:0,ctx:null,data:Object.fromEntries(kinds.map(k=>[k,[]])),tab:'today',operation:'expenses',selection:null,history:[],query:'',status:'',project:'',employee:'',from:'',to:'',page:1,mobileDetail:false,projectSection:'overview',loading:false,error:'',lastRead:0};
  let stage,contentRoot,client,subscription,loadPromise;const scrolls=new Map(),mediaNames=new Map();
