    const operation=state.tab==='operations'?`<nav class="work-subnav-v167" aria-label="운영 세부 화면">${[['expenses','지출·증빙'],['purchases','구매·검수'],['tasks','행정 업무']].map(([value,label])=>`<button type="button" data-work-operation="${value}" class="${state.operation===value?'active':''}">${label}</button>`).join('')}</nav>`:'';
    const addKind=state.tab==='projects'?'projects':state.tab==='employees'?'employees':state.tab==='resources'?'resources':state.tab==='operations'?state.operation:'tasks';
    contentRoot.innerHTML=`<div class="work-shell-v167"><aside class="work-nav-v167"><h2>Work</h2><nav aria-label="Work 메뉴">${tabs.map(([id,label])=>`<button type="button" data-work-tab="${id}" class="${state.tab===id?'active':''}" aria-pressed="${state.tab===id}">${label}</button>`).join('')}</nav>${shortcutsMarkup()}<div class="work-nav-tools-v167">${actionButton('새로고침','refresh')}${actionButton('기록 내보내기','export')}${actionButton('이전 기록 가져오기','legacy')}</div><p data-work-message role="status">${esc(state.error||'')}</p></aside><main class="work-main-v167">${stats}${operation}<div class="work-toolbar-v167"><label class="work-search-v167"><span class="work-sr-v167">검색</span><input data-work-query type="search" placeholder="이름·제목·코드 검색" value="${esc(state.query)}"></label>${actionButton('+ '+labels[addKind],'add',`data-kind="${addKind}"`,'primary')}${state.tab==='employees'?actionButton('업무 배정','add','data-kind="tasks"'):''}<details class="work-filters-v167"><summary>필터</summary><div>${filterSelect('status','상태',Object.entries(statusNames),state.status)}${filterSelect('project','프로젝트',state.data.projects.map(r=>[r.id,r.title]),state.project)}${filterSelect('employee','직원',state.data.employees.filter(e=>e.uid).map(e=>[e.uid,e.name]),state.employee)}<label>시작<input type="date" data-work-filter="from" value="${esc(state.from)}"></label><label>종료<input type="date" data-work-filter="to" value="${esc(state.to)}"></label>${actionButton('필터 초기화','reset-filters')}</div></details></div><div class="work-split-v167 ${state.mobileDetail?'is-detail':''}"><section class="work-list-v167" aria-label="목록"><div class="work-rows-v167"></div><footer class="work-pager-v167"></footer></section><section class="work-detail-v167" aria-label="선택한 기록 상세"></section></div></main></div>`;
    const toolbar=$('.work-toolbar-v167',stage);if(state.tab==='today'){const label=document.createElement('label');label.className='work-today-view-v167';label.innerHTML=`<span class="work-sr-v167">오늘 목록</span><select data-work-today-view>${[['','결정 대기·주요 업무'],['deadlines','가까운 마감'],['employees','직원별 진행'],['milestones','프로젝트 다음 산출물'],['due','오늘 마감'],['review','검토 대기'],['blocked','진행 불가'],['evidence','증빙 보완']].map(([id,text])=>`<option value="${id}" ${state.focusMode===id?'selected':''}>${text}</option>`).join('')}</select>`;$('.work-search-v167',toolbar).after(label);}
