  async function hydrateMedia(){const epoch=state.epoch;await Promise.all($$('[data-work-media-name]',stage).map(async el=>{const id=el.dataset.workMediaName;if(mediaNames.has(id))return;try{const info=await client.call('mediaInfo',{id});if(epoch!==state.epoch||!el.isConnected)return;mediaNames.set(id,info.name);el.textContent=info.name;}catch{if(epoch===state.epoch&&el.isConnected)el.textContent='첨부 확인 필요';}}));}
