    dialog.addEventListener('click',event=>{const add=event.target.closest('[data-repeat-add]'),remove=event.target.closest('[data-repeat-remove]');if(add){const fieldset=add.closest('[data-work-repeater]');$('[data-repeat-rows]',fieldset).insertAdjacentHTML('beforeend',repeaterRow(fieldset.dataset.repeatType));dirty=true;request=uid();}if(remove){remove.closest('[data-work-repeat-row]').remove();dirty=true;request=uid();}});
